<?php use App\Helpers\{View,Csrf,Auth};?><section class="page-head"><span class="eyebrow">TU SELECCIÓN</span><h1>Mi carrito</h1></section><?php if(!$items):?><div class="empty"><span>🧁</span><h2>Tu carrito está vacío</h2><a class="primary btn" href="/catalog">Explorar pasteles</a></div><?php else:?><div class="cart-layout"><form method="post" action="/cart/update" class="panel"><?=Csrf::field()?><?php foreach($items as $i):?><div class="cart-item"><div class="thumb"><?php if($i['image']):?><img src="<?=View::e($i['image'])?>"><?php else:?>🍰<?php endif;?></div><div><h3><?=View::e($i['name'])?></h3><small>$<?=number_format($i['price'],2)?> c/u</small></div><input type="number" min="0" max="<?=$i['stock']?>" name="qty[<?=$i['id']?>]" value="<?=$i['quantity']?>"><strong>$<?=number_format($i['price']*$i['quantity'],2)?></strong></div><?php endforeach;?><button class="secondary">Actualizar carrito</button></form><aside class="summary"><h2>Resumen</h2><div><span>Subtotal</span><strong>$<?=number_format($totals['subtotal'],2)?></strong></div><?php if(Auth::check()):?><form method="post" action="/checkout"><?=Csrf::field()?><label>Canjear recompensa<select name="reward_id"><option value="0">No usar puntos</option><?php foreach($totals['rewards'] as $r):?><option value="<?=$r['id']?>"><?=View::e($r['name'])?> · <?=$r['points_required']?> pts · <?=$r['discount_percent']?>%</option><?php endforeach;?></select></label><button class="primary wide">Confirmar pedido</button></form><?php else:?><a class="primary btn wide" href="/login">Inicia sesión para comprar</a><?php endif;?></aside></div><?php endif;?>